import{z as B,x as E,o as s,c as p,q as o,j as n,D as t,d as r,s as d,S as l,b as e}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"BFS 与无权最短路","description":"","frontmatter":{"title":"BFS 与无权最短路","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/bfs-unweighted.md","filePath":"cs/bfs-unweighted.md","lastUpdated":1791413859000}'),A={name:"cs/bfs-unweighted.md"};function h(f,a,u,m,S,C){const i=E("Mermaid");return s(),p("div",null,[a[2]||(a[2]=o('<h1 id="bfs-与无权最短路" tabindex="-1">BFS 与无权最短路 <a class="header-anchor" href="#bfs-与无权最短路" aria-label="Permalink to &quot;BFS 与无权最短路&quot;">​</a></h1><div class="epigraph"><p>队列按发现次序弹出顶点；在边权为 $1$ 的图上，这就是最短路。</p><footer>—— 据 Moore, The Shortest Path Through a Maze, 1959；CLRS 第 22 章整理</footer></div><p>上一课<a href="/cs/median-of-medians">中位数的中位数</a>收束了数组上的比较算法。图的定义、<a href="/cs/adj-list-matrix">邻接表</a>、<a href="/cs/queue-buffer">队列</a>都已在数据结构课。<a href="/cs/asymptotic-notation">渐近记号</a>够用。本课不重画图。缺口是：表示还不是算法——无权（或边权全 \\(1\\)）时，源点到各点的最短路怎么算。本课只交出 BFS 与层。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>从 \\(s\\) 出发，要 \\(d(s,v)\\)：最少边数。若每次把新发现的邻点丢进栈，得到的是深度优先的某条路，不是最短。缺口是<strong>宽度</strong>：先处理离 \\(s\\) 边数为 \\(i\\) 的全体，再处理 \\(i+1\\)。队列保证弹出次序非降于发现距离。</p><p>循环不变式：队列里是当前层与下一层的 frontier；已出队顶点的 \\(d\\) 已是最短。灰/白/黑只是实现色，不是另一套理论。邻接表上每个点、每条边看常数次，\\(\\Theta(V+E)\\)。</p><p><span class="marginnote">术语翻译：「层」就是「离源点最少要跨几条边」。\\(d[v]=3\\) 读作「从 \\(s\\) 到 \\(v\\) 至少要走 3 步」；每个点被发现时，这个数就是发现者的数加 \\(1\\)，没有别的来源。</span></p><h3 id="bfs-不是「图的遍历」的唯一意思" tabindex="-1">BFS 不是「图的遍历」的唯一意思 <a class="header-anchor" href="#bfs-不是「图的遍历」的唯一意思" aria-label="Permalink to &quot;BFS 不是「图的遍历」的唯一意思&quot;">​</a></h3><p>遍历还可以 DFS。BFS 多给的是距离与一棵广度树（树边指向先发现的前驱）。无权最短路是本课的后置条件；带正权要<a href="/cs/dijkstra">Dijkstra</a>，不要把队列换成「看起来像优先队列」却仍当 BFS。</p><p><span class="marginnote">Moore 的迷宫最短路与图论教科书的 BFS 是同一层。CLRS 22.2 的颜色与 \\(d\\)、$ \\pi$ 是标准记账。本课用邻接表，稠密时矩阵也是 \\(\\Theta(V^2)\\)，稀疏课已说明何时用哪份表示。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>初始化 \\(d[s]=0\\)，其余 \\(\\infty\\)， \\(s\\) 入队。弹出 \\(u\\)，对未发现邻 \\(v\\) 置 \\(d[v]=d[u]+1\\)、\\(\\pi[v]=u\\)，入队。不变式：\\(d\\) 对已发现点正确；队列中点的 \\(d\\) 至多差 \\(1\\)。</p>',12)),(s(),n(l,null,{default:t(()=>[d(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E6%BA%90%20s%22%5D%20--%3E%20Q%5B%22%E9%98%9F%E5%88%97%EF%BC%9A%E6%8C%89%E5%B1%82%22%5D%0A%20%20Q%20--%3E%20U%5B%22%E5%BC%B9%E5%87%BA%20u%22%5D%0A%20%20U%20--%3E%20N%5B%22%E6%9C%AA%E5%8F%91%E7%8E%B0%E9%82%BB%E7%82%B9%E5%85%A5%E9%98%9F%22%5D%0A%20%20N%20--%3E%20Q%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"无权有向、无向都适用；无向把每条无向边当两条有向。负权、分数权本课不处理。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"前驱 \\(\\pi\\) 给出一条最短路，不是全部。多源 BFS 把若干源先入队，相当于加超级源。二分图判定（染色）是同一层遍历的推论，本课点名：奇环当且仅当某非树边连到同层或层差不是 \\(1\\) 的冲突，细节不写完。",-1)),a[6]||(a[6]=e("p",null,"多源 BFS 到底在算什么：把所有源都当 \\(0\\) 层同时起波，每个点的 \\(d\\) 变成「到最近源」的边数。",-1)),(s(),n(l,null,{default:t(()=>[d(i,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E6%BA%90%20A%EF%BC%9Ad%3D0%22%5D%20--%3E%20Q%5B%22%E5%90%8C%E4%B8%80%E9%98%9F%E5%88%97%EF%BC%8C%E4%BA%92%E4%B8%8D%E5%8C%BA%E5%88%86%22%5D%0A%20%20B%5B%22%E6%BA%90%20B%EF%BC%9Ad%3D0%22%5D%20--%3E%20Q%0A%20%20C%5B%22%E6%BA%90%20C%EF%BC%9Ad%3D0%22%5D%20--%3E%20Q%0A%20%20Q%20--%3E%20L1%5B%22%E7%AC%AC%201%20%E5%B1%82%EF%BC%9A%E6%89%80%E6%9C%89%E6%BA%90%E7%9A%84%E9%82%BB%E7%82%B9%22%5D%0A%20%20L1%20--%3E%20L2%5B%22%E7%AC%AC%202%20%E5%B1%82%EF%BC%9A%E7%A6%BB%E6%9C%80%E8%BF%91%E6%BA%90%202%20%E6%9D%A1%E8%BE%B9%22%5D%0A%20%20L2%20--%3E%20R%5B%22d%5Bv%5D%20%3D%20v%20%E5%88%B0%E6%9C%80%E8%BF%91%E6%BA%90%E7%9A%84%E8%B7%9D%E7%A6%BB%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=o('<p><span class="marginnote">数字实例：三处起火点同时烧，一回合蔓延到相邻格。某格第 4 回合才被烧到，说明它离最近的起火点恰是 4 步——多源 BFS 的 \\(d[v]=4\\) 就是这个意思，不必对每个源各跑一遍再取最小。</span></p><p>边权为正但不为 \\(1\\)，层不再等于路径权，必须停用本课算法。</p><p><span class="marginnote">常见误区：初学者容易以为 BFS 天然就是最短路算法；它靠的是「边权全为 \\(1\\)」这一前提，层号才恰好等于路径长度。一旦边权出现 \\(2\\) 或 \\(0.5\\)，先到的点不再保证最短，必须改用 Dijkstra。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不分类回边、不写拓扑序、不跑正权最短路。连通分量：无向图上多次 BFS 即可，本课默认单源。也不把网格迷宫画成新模型：那就是四邻接图。</p><p>后课默认：无权最短路 = BFS，\\(d\\) 为边数，\\(\\Theta(V+E)\\)。DFS 的边类型是下一缺口。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>无权最短路用队列分层，不变式是距离非降。</li><li>邻接表 \\(\\Theta(V+E)\\)；前驱给出一条最短路。</li><li>正权但非单位权，本课算法失效。</li><li>出处：Moore, 1959；CLRS 第 22.2 节。</li></ul>',8))])}const c=B(A,[["render",h]]);export{D as __pageData,c as default};
